// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    // the deployer/owner must be able to receive ETH via transfer
    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);
        address owner = address(this);

        // fund C through its payable fallback
        vm.deal(owner, amount);
        vm.prank(owner);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok);
        require(address(c).balance == amount);

        // owner drains everything
        c.withdrawAll();

        // RULE: after withdrawAll the contract holds no funds
        assertTrue(address(c).balance == 0);
    }
}
